/**
 * dsh-file-mention —— 规则匹配核心（纯函数，零依赖，可独立测试）
 *
 * 实现 gitignore/.aiinclude 风格的路径匹配子集：
 *   - `#` 注释、空行忽略
 *   - `!` 前缀表示否定（最后匹配者生效）
 *   - 末尾 `/` 表示仅目录
 *   - 开头 `/` 表示锚定于基准目录
 *   - 含 `/` 的模式按完整相对路径匹配；不含 `/` 的模式按 basename 任意层级匹配
 *   - `*` 匹配段内任意字符、`?` 匹配单字符、`**` 跨段匹配
 */

/** 段 → 正则片段：支持 *（段内任意）、?（单字符），其余按字面量转义。 */
function segmentToRegex(seg) {
  let out = ''
  for (const ch of seg) {
    if (ch === '*') out += '[^/]*'
    else if (ch === '?') out += '[^/]'
    else out += ch.replace(/[.+^${}()|[\]\\]/g, '\\$&')
  }
  return out
}

/** 编译规则行集合为可复用的匹配规则数组。 */
function compileRules(lines) {
  const rules = []
  for (let raw of lines) {
    raw = raw.trim()
    if (raw === '' || raw.startsWith('#')) continue
    let negate = false
    if (raw.startsWith('!')) {
      negate = true
      raw = raw.slice(1).trim()
    }
    if (raw === '') continue
    const dirOnly = raw.endsWith('/')
    if (dirOnly) raw = raw.slice(0, -1)
    let anchored = raw.startsWith('/')
    if (anchored) raw = raw.slice(1)
    if (raw === '') continue
    const hasSlash = raw.includes('/')
    try {
      // 逐段编译：完整正则（匹配）+ 段列表（剪枝判定用）
      const segs = raw.split('/').map((seg) => {
        if (seg === '**') return { star: true, re: null }
        return { star: false, re: new RegExp('^' + segmentToRegex(seg) + '$') }
      })
      const src = segs.map((s) => (s.star ? '(?:.*)' : s.re.source.slice(1, -1))).join('/')
      rules.push({ negate, dirOnly, anchored, hasSlash, segs, re: new RegExp('^' + src + '$') })
    } catch {
      // 非法模式跳过
    }
  }
  return rules
}

/**
 * 剪枝判定：目录 relPath 是否**可能**通往某条规则的命中？
 * 为 false 时遍历可以安全跳过该目录（.aiinclude 目录规则场景可大幅减负）。
 *
 * - basename 非目录规则（如 `*.log`）：任意层级都可能命中 → 恒 true（不可剪枝）
 * - basename 目录规则（如 `doc/`）：仅目录名匹配时才有意义
 * - 锚定/含斜杠规则（如 `app/build/**`）：目录是某规则段序列的前缀时才可能
 */
function dirMayLeadToMatch(rules, relPath) {
  const pathSegs = relPath.split('/')
  for (const r of rules) {
    if (r.anchored || r.hasSlash) {
      // 段前缀匹配：pathSegs 必须逐段命中规则段前缀；'**' 通吃其后
      let ok = true
      for (let i = 0; i < pathSegs.length; i++) {
        const p = r.segs[i]
        if (p === undefined) {
          ok = false
          break
        }
        if (p.star) break
        if (!p.re.test(pathSegs[i])) {
          ok = false
          break
        }
      }
      if (ok) return true
    } else if (!r.dirOnly) {
      // basename 文件规则：任何目录都可能包含命中文件
      return true
    } else {
      // basename 目录规则：目录名命中即会继承
      const name = pathSegs[pathSegs.length - 1]
      if (r.re.test(name)) return true
    }
  }
  return false
}

/**
 * 返回 rel 命中的最后一条规则（gitignore 语义：最后匹配者生效）；
 * 未命中返回 undefined。
 */
function lastMatchRule(rules, rel, isDir) {
  let win
  for (const r of rules) {
    if (r.dirOnly && !isDir) continue
    if (r.anchored || r.hasSlash) {
      if (r.re.test(rel)) win = r
    } else {
      const base = rel.slice(rel.lastIndexOf('/') + 1)
      if (r.re.test(base) || r.re.test(rel)) win = r
    }
  }
  return win
}

/** 判断相对路径 rel 是否命中规则集（最后匹配者生效，未命中为 false）。 */
function matchRules(rules, rel, isDir) {
  const win = lastMatchRule(rules, rel, isDir)
  return win !== undefined ? !win.negate : false
}

/**
 * 解析 `git status --porcelain -z` 输出为变更文件列表（含归一化状态码）。
 * 每条 `<XY> <path>\0`；重命名/复制（R/C）占两个字段：真实 git -z 格式为
 * `R  NEW\0OLD\0`（**新路径在前**、原路径在后），取当前条目（新路径），
 * 原路径字段直接跳过。路径含空格等特殊字符时依然精确（-z 不做引号转义）。
 *
 * 状态码归一化（客户端用于行尾字母标记）：
 *   `??` 未跟踪 → A；X/Y 任一侧 A → A、D → D、R/C → R；其余（M/U/T/冲突）→ M。
 * 重命名/复制的原路径字段（旧路径）也输出为 `{ path, status: 'D' }`：
 *   旧文件已被移走/删除，状态数据保持完整（git 的 rename 检测可能把「同内容的
 *   新增+删除」配对成 R——此时原路径对应的删除文件若单独出现会丢失其 D 状态）。
 */
function parseStatusZ(text) {
  const dirty = []
  const parts = text.split('\0')
  for (let i = 0; i < parts.length; i++) {
    const entry = parts[i]
    if (entry === '') continue
    const code = entry[0]
    const x = entry[1]
    if (code === 'R' || code === 'C') {
      const path = entry.slice(3)
      if (path !== '') dirty.push({ path, status: 'R' })
      const oldPath = parts[i + 1]
      if (oldPath !== undefined && oldPath !== '') {
        dirty.push({ path: oldPath, status: 'D' })
      }
      i += 1 // 跳过原路径字段（纯路径段，无状态码，不能被误当条目）
    } else if (code === '?' && x === '?') {
      const path = entry.slice(3)
      if (path !== '') dirty.push({ path, status: 'A' })
    } else {
      // XY 两字符后是分隔空格：X=index 状态（entry[0]），Y=worktree 状态（entry[1]）
      let status = 'M'
      for (const s of [code, entry[1]]) {
        if (s === 'A') { status = 'A'; break }
        if (s === 'D') { status = 'D'; break }
        if (s === 'R' || s === 'C') { status = 'R'; break }
      }
      const path = entry.slice(3)
      if (path !== '') dirty.push({ path, status })
    }
  }
  return dirty
}

/**
 * 将仓库根相对路径列表裁剪为 cwd 相对路径（git status --porcelain 在子目录
 * 输出仓库根相对路径，与 git ls-files 的 cwd 相对不对称；prefix 来自
 * `git rev-parse --show-prefix`，含尾部斜杠，如 `sub/`）。
 * 不在 prefix 之下的路径（cwd 外）直接丢弃。
 * 元素可为 string（路径）或 { path, ... }（结构化条目），裁剪后保持原形态。
 */
function stripRepoPrefix(paths, prefix) {
  if (prefix === '') return paths
  return paths
    .map((item) => {
      const path = typeof item === 'string' ? item : item.path
      if (!path.startsWith(prefix)) return null
      const rel = path.slice(prefix.length)
      return typeof item === 'string' ? rel : { ...item, path: rel }
    })
    .filter((x) => x !== null)
}

/**
 * 文件类型图标（4 类 emoji，按扩展名映射；DSH 菜单 icon 为纯文本渲染）。
 * 代码 / 文档 / 图片 / 其他；未知扩展名与隐藏文件归「其他」。
 */
const FILE_ICONS = { code: '⌨️', doc: '📝', image: '🖼️', other: '📄' }
const ICON_EXTS = {
  js: 'code', ts: 'code', tsx: 'code', jsx: 'code', mjs: 'code', cjs: 'code',
  kt: 'code', java: 'code', py: 'code', go: 'code', rs: 'code',
  c: 'code', cpp: 'code', h: 'code', sh: 'code', bat: 'code', ps1: 'code',
  md: 'doc', txt: 'doc', rst: 'doc',
  png: 'image', jpg: 'image', jpeg: 'image', svg: 'image', webp: 'image', gif: 'image', ico: 'image',
}
function fileIcon(relPath) {
  const ext = relPath.slice(relPath.lastIndexOf('.') + 1).toLowerCase()
  return FILE_ICONS[ICON_EXTS[ext]] ?? FILE_ICONS.other
}

/**
 * 按查询词过滤文件列表：匹配 basename 或完整路径（大小写不敏感）。
 * 客户端 @ 菜单的过滤逻辑，独立出来以便测试。
 *
 * 命中排序（score 升序 + rank 升序 + 组内字母序）：
 *   score 0. 精确匹配（完整路径或 basename 与查询词完全相等）
 *   score 1. 前缀匹配（完整路径或 basename 以查询词开头）
 *   score 2. 子串匹配（其余命中项）
 *   rank 0.  git 未提交变更（dirty 集合内）
 *   rank 1.  非隐藏目录（首段不以 . 开头）
 *   rank 2.  隐藏目录
 * 空查询时 score 恒为 0，退化为纯 rank + 字母序（与历史行为一致）。
 */
/**
 * 从文件列表派生全部父目录（相对路径、尾斜杠、去重、字母序）。
 * 目录引用不需要额外扫描：files 已含工作区全部可见文件，其父目录链即完整目录集合
 * （空目录 git 不跟踪、菜单也无意义）。
 * @param {string[]} files 文件路径列表（正斜杠相对路径）
 * @returns {string[]} 目录路径列表，如 `docs/`、`docs/images/`
 */
function deriveDirs(files) {
  const dirs = new Set()
  for (const f of files) {
    let i = f.indexOf('/')
    while (i !== -1) {
      dirs.add(f.slice(0, i + 1))
      i = f.indexOf('/', i + 1)
    }
  }
  return [...dirs].sort()
}

/** basename 提取（目录路径尾斜杠先剥离，如 `docs/` → `docs`）。 */
function baseName(f) {
  const p = f.endsWith('/') ? f.slice(0, -1) : f
  return p.slice(p.lastIndexOf('/') + 1)
}

/**
 * 目录逐级展开：显示的目录深度上限 = 查询词中 `/` 数量 + 1。
 *   - `@app`（无斜杠）→ 只显示顶层目录（app/）
 *   - `@app/`（进入 app）→ 只显示第二层（app/ 的直接子目录，如 app/src/），
 *     更深的 app/src/main/ 不显示——逐级浏览，避免深层子目录排队刷屏
 *   - `@app/src/` → 第三层（app/src/ 的直接子目录）
 * 例外：单段查询时，**basename 以查询词开头的深层目录突破深度限制**——
 *   如 `@10_logcat_analyze` 直达 `docs/10_logcat_analyze/`（快速关联子目录，无需输入完整路径）。
 * 深层目录在 filterFiles 按查询词匹配过滤后不会串味；返回的是「允许展示」的目录全集。
 * @param {string[]} dirs 全量目录（deriveDirs 输出，尾斜杠）
 * @param {string} [query] 当前查询词
 * @returns {string[]} 应展示的目录
 */
function visibleDirs(dirs, query) {
  const q = String(query || '').trim().toLowerCase()
  const depth = (q.match(/\//g) || []).length + 1
  return dirs.filter((d) => {
    const segments = d.slice(0, -1).split('/')
    if (segments.length <= depth) return true
    // 快速关联子目录：单段查询时，basename 以查询词开头的深层目录放行
    // （startsWith 而非 includes，避免短查询词放行大量无关目录）
    if (q !== '' && !q.includes('/')) {
      return segments[segments.length - 1].startsWith(q)
    }
    return false
  })
}

/** 变更文件置顶数量上限（v0.1.14：避免变更过多时压制目录，只置顶最近修改的 N 个）。 */
const TOP_DIRTY = 5

/**
 * 取 cmp 序最小的 k 个元素并返回有序前缀（原地修改 arr）。
 * 快速选择 O(n) 平均 + 前缀 sort，避免大组（数万项）全量排序——菜单只需前 limit 个。
 * @param {unknown[]} arr 候选数组（原地重排）
 * @param {number} k 需要的前缀长度
 * @param {(a:unknown,b:unknown)=>number} cmp 比较器（与 Array.sort 同语义）
 * @returns {unknown[]} 有序的前 k 个元素（原数组引用）
 */
function topK(arr, k, cmp) {
  if (arr.length <= k) {
    arr.sort(cmp)
    return arr
  }
  let lo = 0
  let hi = arr.length - 1
  while (lo < hi) {
    // 中位 pivot（三数取中退化处理）：输入常为已排序数组，pivot 取末尾会 O(n²)
    const mid = (lo + hi) >> 1
    const t0 = arr[mid]
    arr[mid] = arr[hi]
    arr[hi] = t0
    const pivot = arr[hi]
    let i = lo
    for (let j = lo; j < hi; j++) {
      if (cmp(arr[j], pivot) < 0) {
        const t = arr[i]
        arr[i] = arr[j]
        arr[j] = t
        i++
      }
    }
    arr[hi] = arr[i]
    arr[i] = pivot
    if (i === k) break
    if (i < k) lo = i + 1
    else hi = i - 1
  }
  return arr.slice(0, k).sort(cmp)
}

/**
 * 预计算路径元数据索引（v0.1.14 性能）：files 列表不变时可复用，避免每次按键
 * 对数万路径重复 toLowerCase/split——大仓库（3 万文件）下 filterFiles 从 ~30ms 降到 ~5ms。
 *
 * 段索引（segment index）：路径按 `/` 拆段，段名按小写首字符分桶（segBuckets:
 * Map<首字符, 段名[]>）+ 段名 → 路径倒排（segments: Map<段名, path[]>）。
 * 单段查询（如 `@seal`）只遍历首字符桶（路径数的 ~1/26），中段子串命中从全扫描
 * O(路径数×长度) 降到 O(桶大小)——3 万文件 `@seal` ~20ms → ~2ms。
 * @param {string[]} files 文件/目录路径列表
 * @returns {{lower:Map,base:Map,isDir:Map,isHidden:Map,segments:Map,segBuckets:Map}}
 *   各路径的小写/ basename 小写/目录标志/隐藏标志 + 段倒排 + 段首字符桶
 */
function buildIndex(files) {
  const lower = new Map()
  const base = new Map()
  const isDir = new Map()
  const isHidden = new Map()
  const segments = new Map() // 段名（原样）→ 路径[]
  const segBuckets = new Map() // 段名小写首字符 → 段名[]
  for (const f of files) {
    lower.set(f, f.toLowerCase())
    base.set(f, baseName(f).toLowerCase())
    isDir.set(f, f.endsWith('/'))
    isHidden.set(f, f.split('/')[0].startsWith('.'))
    const segs = (f.endsWith('/') ? f.slice(0, -1) : f).split('/')
    for (const s of segs) {
      if (s === '') continue
      let arr = segments.get(s)
      if (arr === undefined) {
        arr = []
        segments.set(s, arr)
        const c = s[0].toLowerCase()
        let bucket = segBuckets.get(c)
        if (bucket === undefined) {
          bucket = []
          segBuckets.set(c, bucket)
        }
        bucket.push(s)
      }
      arr.push(f)
    }
  }
  // 段路径列表排序（warm 后台一次性）：单段命中时可直接按序 slice（O(n) 无 sort/topK）
  for (const arr of segments.values()) arr.sort()
  return { lower, base, isDir, isHidden, segments, segBuckets }
}

/**
 * 按查询词过滤文件/目录列表：匹配 basename 或完整路径（大小写不敏感）。
 * 客户端 @ 菜单的过滤逻辑，独立出来以便测试。
 *
 * 命中排序（score 升序 + rank 升序 + 组内字母序）：
 *   score 0. 精确匹配（完整路径或 basename 与查询词完全相等）
 *   score 1. 前缀匹配（basename 或完整路径以查询词开头）
 *   score 2. 子串匹配（basename 或完整路径包含查询词）
 *   rank 0. 未提交变更（置顶；数组形态按 mtime 降序只取前 TOP_DIRTY 个，
 *            无 mtime 的旧格式/Set 形态为全量置顶）
 *   rank 1. 目录（集中置前，便于快速选择目录引用）
 *   rank 2. 普通文件（含未置顶的其余变更文件）
 *   rank 3. 隐藏路径（首段以 `.` 开头）
 * @param {string[]} files 文件/目录路径列表
 * @param {string} [query] 查询词
 * @param {number} [limit] 返回条数上限
 * @param {Set<string>|Array<{path:string,mtime?:number}>|string[]} [dirty] 未提交变更：
 *   Set → 全量置顶；数组 → 含 mtime 时按最近修改取 TOP_DIRTY 个置顶（其余 rank 2），
 *   全部无 mtime（旧版 Host string[] 等）→ 全量置顶
 * @param {ReturnType<buildIndex>} [index] 预计算索引（files 不变时复用）
 */
function filterFiles(files, query, limit = 100, dirty, index) {
  const q = String(query || '').trim().toLowerCase()
  let topDirty = null // Map<path, mtime>：置顶变更集（rank 0，组内按 mtime 降序）
  if (dirty instanceof Set) {
    topDirty = new Map([...dirty].map((p) => [p, undefined]))
  } else if (Array.isArray(dirty) && dirty.length > 0) {
    const entries = dirty.map((d) => (typeof d === 'string' ? { path: d } : d))
    if (entries.some((d) => typeof d.mtime === 'number')) {
      topDirty = new Map(
        [...entries]
          .sort(
            (a, b) =>
              (b.mtime ?? 0) - (a.mtime ?? 0) ||
              (a.path < b.path ? -1 : a.path > b.path ? 1 : 0),
          )
          .slice(0, TOP_DIRTY)
          .map((d) => [d.path, d.mtime]),
      )
    } else {
      topDirty = new Map(entries.map((d) => [d.path, d.mtime]))
    }
  }
  // 性能优化（v0.1.14）：短查询词匹配数千项时全量 sort 且比较器重复计算 toLowerCase
  // 导致每次按键 40ms+ 卡顿。改为：
  //   1) 按 score 分层（精确/前缀/子串），组内排序后拼接，达到 limit 即停（子串大组不排序）；
  //   2) rank 预计算缓存（比较器查表，不重复 split/startsWith）；
  //   3) 传入 buildIndex 预计算索引时，lowercase/basename/目录/隐藏标志查表（3 万文件 ~30ms → ~5ms）。
  const rankCache = new Map()
  const rankOf = (f) => {
    let r = rankCache.get(f)
    if (r !== undefined) return r
    if (topDirty !== null && topDirty.has(f)) {
      r = 0
    } else if (index !== undefined) {
      // 目录项可能不在 index（index 只覆盖 files，filterFiles 输入含 visibleDirs 目录）→ 回退
      const h = index.isHidden.get(f)
      const d = index.isDir.get(f)
      r = h !== undefined ? (h ? 3 : d ? 1 : 2)
        : f.split('/')[0].startsWith('.') ? 3
        : f.endsWith('/') ? 1
        : 2
    } else {
      r = f.split('/')[0].startsWith('.') ? 3 // 隐藏（含隐藏目录）沉底
        : f.endsWith('/') ? 1 // 目录：变更文件后、普通文件前
        : 2
    }
    rankCache.set(f, r)
    return r
  }
  const lowerOf = (f) => {
    if (index !== undefined) {
      const v = index.lower.get(f)
      if (v !== undefined) return v
    }
    return f.toLowerCase()
  }
  const baseOf = (f) => {
    if (index !== undefined) {
      const v = index.base.get(f)
      if (v !== undefined) return v
    }
    return baseName(f).toLowerCase()
  }
  const out = []
  // 12 桶（score 0..2 × rank 0..3）直接产出：桶保持输入序（有序时无需 sort/topK），
  // rank0 桶按 mtime 降序；按 score → rank 顺序取桶前缀至 limit。
  const collectBuckets = (b9) => {
    for (let s = 0; s < 3; s++) {
      const b = b9[s * 4]
      if (b.length > 1) {
        b.sort((a, c) => (topDirty?.get(c) ?? 0) - (topDirty?.get(a) ?? 0))
      }
    }
    for (let s = 0; s < 3 && out.length < limit; s++) {
      for (let r = 0; r < 4 && out.length < limit; r++) {
        const b = b9[s * 4 + r]
        const need = limit - out.length
        for (let i = 0; i < need && i < b.length; i++) out.push(b[i])
      }
    }
  }
  const groups = [[], [], []] // score 0 精确 / 1 前缀 / 2 子串（空查询全部 0）
  let needFullScan = false // 快速路径命中不足 limit → 清空结果走全扫描
  if (q === '') {
    groups[0] = [...files]
  } else if (index !== undefined && index.segBuckets !== undefined && !q.includes('/')) {
    // 段索引快速路径（单段查询）：遍历首字符桶的段名（~路径数/26），段名包含 q 的
    // 段 → 倒排路径。命中集合覆盖前缀（段前缀）与子串（段包含）语义；
    // 跨段子串（如 'b/c' 匹配 'ab/cd'）不再命中——实际查询中不存在，可忽略。
    // 恰一个命中段时（最常见：包名/目录名查询），段路径列表已排序 →
    // 按 (score, rank) 12 桶直接分流（O(n) 无 sort/topK）并直接产出；
    // 多命中段合并需去重，回退 Set+topK（走 groups 统一循环）。
    const bucket = index.segBuckets.get(q[0])
    if (bucket !== undefined) {
      const hitSegs = []
      for (const seg of bucket) {
        if (seg.toLowerCase().includes(q)) hitSegs.push(seg)
      }
      if (hitSegs.length === 1) {
        const segPaths = index.segments.get(hitSegs[0])
        if (segPaths !== undefined) {
          // 单命中段：段路径列表已排序 → 12 桶直接分流（O(n) 无 sort/topK）
          const b9 = Array.from({ length: 12 }, () => [])
          for (const f of segPaths) {
            const lower = lowerOf(f)
            const base = baseOf(f)
            const s = lower === q || base === q ? 0
              : base.startsWith(q) || lower.startsWith(q) ? 1
              : 2
            b9[s * 4 + rankOf(f)].push(f)
          }
          collectBuckets(b9)
          if (out.length >= limit) return out
          out.length = 0 // 命中不足 limit：清空，走全扫描补充
          needFullScan = true
        }
      } else if (hitSegs.length > 1) {
        const hit = new Set()
        for (const seg of hitSegs) {
          const ps = index.segments.get(seg)
          if (ps !== undefined) for (const p of ps) hit.add(p)
        }
        for (const f of hit) {
          const lower = lowerOf(f)
          const base = baseOf(f)
          if (lower === q || base === q) groups[0].push(f)
          else if (base.startsWith(q) || lower.startsWith(q)) groups[1].push(f)
          else groups[2].push(f)
        }
      }
    }
  } else if (index !== undefined && index.segBuckets !== undefined && q.includes('/')) {
    // 含 '/' 查询（用户删除路径的主场景）：q 拆段，取倒排列表最短的段缩小候选
    // （如 com/intian/seal → 'seal' 段），候选路径做「路径小写包含 q」验证——
    // 与旧语义完全一致，但候选规模从全库降到该段子树；段列表有序 → 12 桶直接产出。
    const qSegs = q.split('/').filter((s) => s !== '')
    let bestSeg = null
    let bestLen = Infinity
    for (const s of qSegs) {
      const arr = index.segments.get(s)
      if (arr !== undefined && arr.length < bestLen) {
        bestLen = arr.length
        bestSeg = s
      }
    }
    if (bestSeg === null) {
      needFullScan = true // q 段都不在索引（罕见）：全扫描
    } else {
      const segPaths = index.segments.get(bestSeg)
      const b9 = Array.from({ length: 12 }, () => [])
      for (const f of segPaths) {
        const lower = lowerOf(f)
        if (!lower.includes(q)) continue
        const base = baseOf(f)
        const s = lower === q || base === q ? 0
          : base.startsWith(q) || lower.startsWith(q) ? 1
          : 2
        b9[s * 4 + rankOf(f)].push(f)
      }
      collectBuckets(b9)
      if (out.length >= limit) return out
      out.length = 0 // 最短段命中不足 limit：清空，走全扫描补充
      needFullScan = true
    }
  } else {
    needFullScan = true // 无索引 → 全扫描
  }
  if (needFullScan) {
    // 前缀先行（startsWith 快速失败）：第一遍只收集精确/前缀命中——
    // 大仓库前缀命中通常已 ≥limit（如 @a 命中 app/ 前缀段），子串全扫描（includes，最贵）
    // 只在精确+前缀不足 limit 时才执行，避免每次按键对数万长路径做子串扫描
    for (const f of files) {
      const lower = lowerOf(f)
      const base = baseOf(f)
      if (lower === q || base === q) {
        groups[0].push(f)
      } else if (base.startsWith(q) || lower.startsWith(q)) {
        groups[1].push(f)
      }
    }
    if (groups[0].length + groups[1].length < limit) {
      for (const f of files) {
        const lower = lowerOf(f)
        const base = baseOf(f)
        if (lower === q || base === q || base.startsWith(q) || lower.startsWith(q)) continue
        if (base.includes(q) || lower.includes(q)) groups[2].push(f)
      }
    }
  }
  for (const g of groups) {
    if (out.length >= limit) break
    // 组内排序：rank 升序；rank 0 组内 mtime 降序（相等/缺失回退字母序）；其余字母序
    const cmp = (a, b) => {
      const ra = rankOf(a)
      const rb = rankOf(b)
      if (ra !== rb) return ra - rb
      if (ra === 0) {
        const ma = topDirty?.get(a) ?? 0
        const mb = topDirty?.get(b) ?? 0
        if (ma !== mb) return mb - ma
      }
      return a < b ? -1 : a > b ? 1 : 0
    }
    const need = limit - out.length
    // top-k 部分排序：大组（数万项）只需前 need 个，避免全量 sort
    const picked = topK(g, need, cmp)
    for (let i = 0; i < picked.length; i++) out.push(picked[i])
  }
  return out
}

/**
 * 将嵌套目录 `.aiinclude` 的规则行展平为「根相对」规则行，以便与根规则
 * 合并成一个规则集（last-match-wins 天然实现层级覆盖：后读入的嵌套规则优先）。
 *
 * 语义对齐 gitignore：目录 D 下的规则相对 D 生效——
 *   - 斜杠模式（`/x`、`x/y`、`x/`）：直接加 D 前缀；
 *   - basename 文件模式（`x`）：展开为 `D/x`（直接子级）与 `D/**` 跨段形式（任意深度）；
 *   - basename 目录模式（`x/`）：展开为 `D/x/` 与 `D/**` 跨段形式；
 *   - `**` 前缀模式（如 `**` + `/x`）：额外补 `D/x`（gitignore 语义：匹配 D 本身及其下任意深度）；
 *   - 取反 `!` 前缀保留，按行序参与 last-match-wins。
 *
 * @param {string} dir 嵌套文件所在目录（根相对，无首尾斜杠，如 `doc/sub`）
 * @param {string[]} lines 该 .aiinclude 的原始行
 * @returns {string[]} 展平后的规则行
 */
function flattenNestedRules(dir, lines) {
  const out = []
  for (let raw of lines) {
    raw = raw.trim()
    if (raw === '' || raw.startsWith('#')) continue
    let negate = ''
    if (raw.startsWith('!')) {
      negate = '!'
      raw = raw.slice(1).trim()
    }
    if (raw === '') continue
    const dirOnly = raw.endsWith('/')
    if (dirOnly) raw = raw.slice(0, -1)
    const anchored = raw.startsWith('/')
    if (anchored) raw = raw.slice(1)
    if (raw === '') continue
    const base = dir + '/' + raw
    if (anchored || raw.includes('/')) {
      out.push(negate + base + (dirOnly ? '/' : ''))
      if (raw.startsWith('**/')) {
        out.push(negate + dir + '/' + raw.slice(3) + (dirOnly ? '/' : ''))
      }
    } else if (dirOnly) {
      out.push(negate + base + '/')
      out.push(negate + dir + '/**/' + raw + '/')
    } else {
      out.push(negate + base)
      out.push(negate + dir + '/**/' + raw)
    }
  }
  return out
}

// ---- src/host.js (inlined) ----
/**
 * dsh-file-mention —— Host 半体
 *
 * 通过 `webServer` 注册 `/file-mention/list` HTTP 路由：
 *   - 解析会话工作区（ctx.sessions）
 *   - 通过 git ls-files 列出跟踪文件 + 未跟踪非忽略文件（两者都天然遵守
 *     .gitignore，排除编译产物；新建文件无需 git add 即可 @ 引用）
 *   - 读取工作区根目录 .aiinclude，把被忽略但 AI 需要的文件重新纳入
 *   - git 不可用/非仓库时回退为 .gitignore 解析 + 全量扫描
 *
 * 构建时由 scripts/build.mjs 将 src/core.js 内联进来，产物无任何外部依赖。
 */
import { stat } from 'node:fs/promises'
import { join } from 'node:path'

const name = '@hucj/dsh-file-mention'
const inject = ['sessions', 'webServer']

/** 请求体大小上限（防御超大请求）。 */
const BODY_CAP_BYTES = 64 * 1024

/** 遍历时跳过的重型目录（.aiinclude 命中可覆盖）。 */
const SKIP = new Set([
  '.git', 'node_modules', '.gradle', '.idea', '.kotlin', '.cxx',
  '.externalNativeBuild', 'build', 'out', 'target', 'dist', 'release',
  'debug', '.dsh', '.agents', '.claude', '.codex', 'storages', 'sessions',
])
/** 文件总数上限（防超大仓库：列表体积、传输、客户端每次按键排序成本）。 */
const CAP = 10000
/** 遍历深度上限（真实项目普遍 ≤20 层，32 留足余量）。 */
const MAX_DEPTH = 32

/** git 结果缓存 TTL：仓库根几乎不变；跟踪列表变化慢；status 变化最快。 */
const GIT_ROOT_TTL = 60_000
const GIT_TRACKED_TTL = 15_000
const GIT_DIRTY_TTL = 5_000
const gitRootCache = new Map() // cwd -> { root, prefix, at }（prefix = rev-parse --show-prefix）
const gitTrackedCache = new Map() // cwd -> { files, at }
const gitDirtyCache = new Map() // cwd -> { dirty, at }
const gitUntrackedCache = new Map() // cwd -> { files, deleted, at }（未跟踪非忽略 + 已删除文件，与 dirty 同 TTL）
const extrasCache = new Map() // cwd -> { extras, at }（.aiinclude 收集结果，与 tracked 同 TTL）

/** 读取 TTL 缓存条目；未过期返回条目，过期或缺失返回 null。 */
function cacheGet(map, key, ttl, now) {
  const entry = map.get(key)
  if (entry === undefined || now - entry.at >= ttl) return null
  return entry
}

/** 会话 header cwd 的持久化回退缓存：sessionId -> { cwd, at }。 */
const sessionCwdCache = new Map()
const SESSION_CWD_TTL = 60_000

/**
 * 从持久化层解析会话的 cwd（ctx.sessions 内存注册表缺失时使用，如历史对话）。
 * 返回 undefined 表示解析失败；结果按 sessionId 缓存 60s。
 */
async function resolveCwdFromPersistence(ctx, sessionId) {
  if (typeof sessionId !== 'string' || sessionId.length === 0) return undefined
  const memo = sessionCwdCache.get(sessionId)
  if (memo !== undefined && Date.now() - memo.at < SESSION_CWD_TTL) return memo.cwd
  const persistence = ctx.get('sessionPersistence')
  if (persistence === undefined) return undefined
  let cwd
  try {
    const info = await persistence.inspect(sessionId)
    // SessionInspection 结构取 header 字段（meta/header/sessionHeader 均防御）
    const meta =
      info !== null && typeof info === 'object'
        ? info.meta ?? info.header ?? info.sessionHeader ?? info.session?.header
        : undefined
    cwd = meta !== null && typeof meta === 'object' && typeof meta.cwd === 'string' ? meta.cwd : undefined
  } catch {
    cwd = undefined
  }
  sessionCwdCache.set(sessionId, { cwd, at: Date.now() })
  return cwd
}

/** 安全读取文本文件；不存在或非文件返回 undefined。 */
async function readTextSafe(fs, path) {
  try {
    const target = await fs.resolve(path)
    const info = await fs.stat(target)
    if (info === undefined || info.type !== 'file') return undefined
    return await fs.readText(target)
  } catch {
    return undefined
  }
}

/**
 * 递归遍历收集命中的文件。
 *
 * - `includeFile(p)`：文件级命中判定（仅在未被继承时检查）。
 * - `inheritDir(p)`：目录级规则状态，返回 true（纳入并继承给子级）、
 *   false（显式排除，阻断继承）或 null（无规则，沿用父级继承状态）。
 *   这是 .aiinclude 目录规则（doc/）与否定规则（!doc/private/）的语义基础。
 * - `mayContain(p)`：可选剪枝判定；目录不可能通往任何命中时跳过递归，
 *   大幅降低 .aiinclude 目录规则场景的遍历开销。
 */
async function walkFiles(fs, dirTarget, includeFile, inheritDir, mayContain) {
  const out = []
  const walk = async (target, relPath, level, inherited) => {
    if (out.length >= CAP || level > MAX_DEPTH) return
    let entries
    try {
      entries = await fs.listDir(target)
    } catch {
      return
    }
    for (const entry of entries) {
      if (out.length >= CAP) return
      if (entry.type === 'directory') {
        const p = relPath === '' ? entry.name : relPath + '/' + entry.name
        let matched = inherited
        if (inheritDir !== null && inheritDir !== undefined) {
          const state = inheritDir(p)
          if (state !== null) matched = state
        }
        if (SKIP.has(entry.name) && !matched) continue
        if (!matched && mayContain !== undefined && mayContain !== null && !mayContain(p)) continue
        await walk(entry.target, p, level + 1, matched)
      } else if (entry.type === 'file') {
        const p = relPath === '' ? entry.name : relPath + '/' + entry.name
        if (inherited || includeFile(p)) out.push(p)
      }
    }
  }
  await walk(dirTarget, '', 0, false)
  return out
}

/** 运行 git 命令并返回 stdout；失败或非零退出返回 undefined。 */
async function runGit(ctx, cwd, args) {
  const sp = ctx.get('subprocess')
  if (sp === undefined) return undefined
  try {
    const handle = sp.spawn({
      // core.quotepath=false：非 ASCII 路径原样输出（Linux 默认会八进制转义中文名）
      argv: ['git', '-c', 'core.quotepath=false', ...args],
      cwd,
      stdio: {
        stdin: 'ignore',
        stdout: { maxBytes: 8 * 1024 * 1024 },
        stderr: { maxBytes: 65536 },
      },
      graceMs: 5000,
    })
    const outcome = await handle.done
    const text = handle.collected.stdout !== undefined ? handle.collected.stdout.readFrom(0).text : ''
    return outcome.exitCode === 0 ? text : undefined
  } catch (error) {
    console.error('[file-mention] git failed:', error)
    return undefined
  }
}

/** 路径统一为正斜杠形式。 */
function norm(p) {
  return typeof p === 'string' ? p.replace(/\\/g, '/') : ''
}

/** 读取 JSON 请求体；为空或解析失败返回 null。 */
async function readJsonBody(req) {
  const chunks = []
  let total = 0
  for await (const chunk of req) {
    const part = chunk
    total += part.length
    if (total > BODY_CAP_BYTES) {
      req.destroy()
      return null
    }
    chunks.push(part)
  }
  const text = Buffer.concat(chunks).toString('utf8')
  if (text === '') return null
  try {
    return JSON.parse(text)
  } catch {
    return null
  }
}

/** 写入 JSON 响应。 */
function json(res, value, status = 200) {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' })
  res.end(JSON.stringify(value))
}

/** 嵌套 .aiinclude 规则合并结果的缓存 TTL（毫秒）。 */
const AI_MEMO_TTL = 60_000
/** 嵌套 .aiinclude 发现数量上限（防御性）。 */
const AI_NESTED_CAP = 50
/** 嵌套规则合并缓存：cwd → { at, rules }。 */
const aiMemo = new Map()

/**
 * 全量遍历（仅跳过 SKIP 目录）发现各子目录中的 `.aiinclude` 文件，
 * 返回其所在目录列表（根相对路径）。用于加载嵌套配置。
 */
async function discoverNestedAiinclude(fs, root) {
  const dirs = []
  const walk = async (target, relPath, level) => {
    if (dirs.length >= AI_NESTED_CAP || level >= MAX_DEPTH) return
    let entries
    try {
      entries = await fs.listDir(target)
    } catch {
      return
    }
    for (const entry of entries) {
      if (dirs.length >= AI_NESTED_CAP) return
      if (entry.type === 'directory') {
        if (SKIP.has(entry.name)) continue
        await walk(entry.target, relPath === '' ? entry.name : relPath + '/' + entry.name, level + 1)
      } else if (entry.type === 'file' && entry.name === '.aiinclude') {
        if (relPath !== '') dirs.push(relPath)
      }
    }
  }
  await walk(root, '', 0)
  return dirs
}

/**
 * 加载工作区的 .aiinclude 规则（根 + 嵌套，合并为单一规则集）。
 *
 * - 根 .aiinclude 不存在 → 返回 null（不启用 .aiinclude 逻辑，零开销）。
 * - 根存在 → 全量发现嵌套 .aiinclude（SKIP 目录内的不读），规则展平为根相对
 *   后按行序追加，last-match-wins 使嵌套规则覆盖根规则；`!` 否定同样参与，
 *   与遍历继承逻辑（inheritDir）自然协作。
 * - 结果按 cwd 内存缓存 AI_MEMO_TTL（60s），避免每次请求重复全量扫描。
 */
async function loadAiRules(fs, cwd, root) {
  const memo = aiMemo.get(cwd)
  if (memo !== undefined && Date.now() - memo.at < AI_MEMO_TTL) return memo.rules
  const rootText = await readTextSafe(fs, cwd + '/.aiinclude')
  const lines = []
  if (rootText !== undefined) {
    lines.push(...rootText.split(/\r?\n/))
    const nestedDirs = await discoverNestedAiinclude(fs, root)
    for (const dir of nestedDirs) {
      const text = await readTextSafe(fs, cwd + '/' + dir + '/.aiinclude')
      if (text !== undefined) lines.push(...flattenNestedRules(dir, text.split(/\r?\n/)))
    }
  }
  const rules = lines.length > 0 ? compileRules(lines) : null
  aiMemo.set(cwd, { at: Date.now(), rules })
  return rules
}

function apply(ctx) {
  const handler = async (req, res) => {
    if (req.method !== 'POST') {
      res.writeHead(405)
      res.end()
      return
    }
    const contentType = req.headers['content-type'] ?? ''
    if (!contentType.toLowerCase().startsWith('application/json')) {
      res.writeHead(415)
      res.end()
      return
    }
    const body = await readJsonBody(req)
    const args = body !== null && typeof body === 'object' && !Array.isArray(body) ? body : null
    const sessionId =
      args !== null && typeof args === 'object' && typeof args.sessionId === 'string'
        ? args.sessionId
        : undefined
    const session = sessionId !== undefined ? ctx.sessions.get(sessionId) : undefined
    let cwd = session !== undefined && session.header !== undefined ? session.header.cwd : undefined
    if (typeof cwd !== 'string' || cwd.length === 0) {
      // 内存注册表（ctx.sessions）只含活跃/已恢复会话；左侧历史对话不在其中时，
      // 回退到持久化层读取会话 header 拿 cwd（60s 缓存，避免每次请求读盘）。
      cwd = await resolveCwdFromPersistence(ctx, sessionId)
    }
    if (typeof cwd !== 'string' || cwd.length === 0) {
      json(res, { files: [] })
      return
    }
    const fs = ctx.get('fs')
    if (fs === undefined) {
      json(res, { files: [] })
      return
    }
    try {
      const root = await fs.resolve(cwd)
      let files = []
      let dirty = []

      // 1) git 跟踪文件：天然遵守 .gitignore，排除编译产物
      //    结果分层缓存（root 60s / tracked 15s / dirty 5s），TTL 内不重复跑 git 子进程；
      //    陈旧上限即 TTL，客户端侧 30s SWR 缓存比它更"旧"，因此整体一致性不受影响。
      const now = Date.now()
      const rootEntry = cacheGet(gitRootCache, cwd, GIT_ROOT_TTL, now)
      let repoRoot = ''
      let repoPrefix = ''
      if (rootEntry !== null) {
        repoRoot = rootEntry.root
        repoPrefix = rootEntry.prefix ?? ''
      } else {
        const rootText = await runGit(ctx, cwd, ['rev-parse', '--show-toplevel', '--show-prefix'])
        if (rootText !== undefined) {
          const lines = rootText.split(/\r?\n/)
          repoRoot = norm((lines[0] ?? '').trim())
          // 第二行：cwd 在仓库中的前缀（含尾部斜杠，如 `sub/`；仓库根为空）
          repoPrefix = (lines[1] ?? '').trim()
        }
        // 非仓库也缓存（root=''），60s 内不再重复探测；git init 后最多 60s 识别
        gitRootCache.set(cwd, { root: repoRoot, prefix: repoPrefix, at: now })
      }

      // 注：git ls-files（-c/-o/-d）在 cwd 下运行，输出路径天然相对 cwd（子目录
      // 会话同样成立，无需裁剪）；而 git status --porcelain 在子目录输出**仓库根
      // 相对**路径，dirty 必须按 repoPrefix 裁剪（见 1b）。
      const trackedEntry = cacheGet(gitTrackedCache, cwd, GIT_TRACKED_TTL, now)
      if (trackedEntry !== null) {
        files = [...trackedEntry.files]
      } else if (repoRoot !== '') {
        const trackedText = await runGit(ctx, cwd, ['ls-files', '-c'])
        if (trackedText !== undefined) {
          files = trackedText
            .split(/\r?\n/)
            .map((l) => l.trim())
            .filter((l) => l !== '')
          // 存副本：后续 1d/extras 的 push 不得污染缓存数组（否则已删/已改的
          // untracked 会借 tracked 15s 缓存残留，超出自身 5s TTL）
          gitTrackedCache.set(cwd, { files: [...files], at: Date.now() })
        }
      } else {
        // 回退：git 不可用/非仓库时，解析 .gitignore 后全量扫描（结果同样缓存 15s）
        const ignoreText = await readTextSafe(fs, cwd + '/.gitignore')
        const rules = compileRules(ignoreText !== undefined ? ignoreText.split(/\r?\n/) : [])
        files = await walkFiles(fs, root, (p) => !matchRules(rules, p, false), null)
        gitTrackedCache.set(cwd, { files: [...files], at: Date.now() })
      }

      // 1b) 未提交变更（staged + unstaged + 删除 + 未跟踪）：@ 默认排序优先展示
      const dirtyEntry = cacheGet(gitDirtyCache, cwd, GIT_DIRTY_TTL, now)
      if (dirtyEntry !== null) {
        dirty = [...dirtyEntry.dirty]
      } else if (repoRoot !== '') {
        const statusText = await runGit(ctx, cwd, ['status', '--porcelain', '-z'])
        if (statusText !== undefined) {
          // status 输出仓库根相对路径（与 ls-files 不对称）：按 repoPrefix 裁剪为
          // cwd 相对，cwd 外的变更条目直接丢弃；条目为 { path, status }
          dirty = stripRepoPrefix(
            parseStatusZ(statusText).filter((d) => d.path !== '' && !d.path.endsWith('/')), // 丢弃 `?? dir/` 折叠死条目
            repoPrefix,
          )
          gitDirtyCache.set(cwd, { dirty: [...dirty], at: Date.now() })
        }
      }

      // 1c) 未跟踪且未被忽略的文件（新建文件）：git status 会把整个未跟踪目录折叠成
      //     一条 `?? dir/`，再经下方末尾 '/' 过滤后彻底丢失，新文件永远进不了菜单；
      //     git ls-files -o --exclude-standard 输出单个文件路径，且天然遵守
      //     .gitignore（编译产物不进来）。与 dirty 同 TTL（新建/删除变化最快）。
      const untrackedEntry = cacheGet(gitUntrackedCache, cwd, GIT_DIRTY_TTL, now)
      let untracked = []
      let deleted = []
      if (untrackedEntry !== null) {
        untracked = [...untrackedEntry.files]
        deleted = [...(untrackedEntry.deleted ?? [])]
      } else if (repoRoot !== '') {
        const untrackedText = await runGit(ctx, cwd, ['ls-files', '-o', '--exclude-standard'])
        if (untrackedText !== undefined) {
          untracked = untrackedText
            .split(/\r?\n/)
            .map((l) => l.trim())
            .filter((l) => l !== '')
          // 1c-2) 已删除文件（index 有、工作区无，如未 git rm 的手动删除）：
          //       git ls-files -c 仍会列出，@ 后模型读取失败——一并收集待剔除
          const deletedText = await runGit(ctx, cwd, ['ls-files', '-d'])
          deleted =
            deletedText === undefined
              ? []
              : deletedText
                  .split(/\r?\n/)
                  .map((l) => l.trim())
                  .filter((l) => l !== '')
          gitUntrackedCache.set(cwd, { files: [...untracked], deleted: [...deleted], at: Date.now() })
        }
      }

      // 1d) 未跟踪文件并入主列表（新文件无需 git add 即可 @ 引用），并标记为变更
      //     优先（status: 'A'）——dirty 只参与客户端排序/行尾标记，不新增 files 条目。
      const seenAll = new Set(files)
      const dirtySet = new Set(dirty.map((d) => d.path))
      for (const p of untracked) {
        if (p === '' || p.endsWith('/')) continue
        if (!seenAll.has(p)) {
          seenAll.add(p)
          files.push(p)
        }
        if (!dirtySet.has(p)) {
          dirtySet.add(p)
          dirty.push({ path: p, status: 'A' })
        }
      }

      // 2) .aiinclude：重新纳入被忽略/未跟踪但 AI 需要的文件（支持子目录嵌套配置）
      //    extras 收集结果同样缓存 15s（与 tracked 同 TTL）——该 walk 遍历 doc/ 级
      //    子树（实测 ~370ms/次），是热请求的大头；aiRules 为 null（无配置）时
      //    整个逻辑跳过，因此缓存不会在配置被删除后残留。
      const aiRules = await loadAiRules(fs, cwd, root)
      if (aiRules !== null) {
        let extras
        const extrasEntry = cacheGet(extrasCache, cwd, GIT_TRACKED_TTL, now)
        if (extrasEntry !== null) {
          extras = extrasEntry.extras
        } else {
          extras = await walkFiles(
            fs,
            root,
            (p) => matchRules(aiRules, p, false),
            (p) => {
              const win = lastMatchRule(aiRules, p, true)
              return win === undefined ? null : !win.negate
            },
            (p) => dirMayLeadToMatch(aiRules, p),
          )
          extrasCache.set(cwd, { extras, at: Date.now() })
        }
        const seen = new Set(files)
        for (const p of extras) {
          if (!seen.has(p)) {
            seen.add(p)
            files.push(p)
          }
        }
      }

      // 2b) 剔除已删除文件（物理不存在，@ 后模型读不到）：files 与 dirty 中
      //     对应条目一并清除（dirty 的 D 死条目保留无意义）。
      if (deleted.length > 0) {
        const gone = new Set(deleted)
        files = files.filter((p) => !gone.has(p))
        dirty = dirty.filter((d) => !gone.has(d.path))
      }

      // 2c) 变更文件补充修改时间（mtime）：客户端只置顶最近修改的 TOP_DIRTY 个，
      //     避免变更过多时压制目录。dsh 的 fs 服务 stat 不提供 mtime（仅
      //     {version,type,size}），此处直接 node:fs stat——dirty 数量少（几十个内）、
      //     并行毫秒级；stat 失败（竞态删除等）保留条目但无 mtime（客户端全量置顶兜底）。
      if (dirty.length > 0) {
        dirty = await Promise.all(
          dirty.map(async (d) => {
            try {
              const st = await stat(join(cwd, d.path))
              return { ...d, mtime: st.mtimeMs }
            } catch {
              return d
            }
          }),
        )
      }

      files = files.filter((p) => p !== '' && !p.endsWith('/')).slice(0, CAP).sort()
      // cwd 用于客户端按工作区共享缓存（同工作区多会话只扫描一次）
      json(res, { files, dirty, cwd })
    } catch (error) {
      console.error('[file-mention] list failed:', error)
      json(res, { files: [], dirty: [] })
    }
  }

  ctx.effect(
    () => ctx.webServer.register({ kind: 'exact', path: '/file-mention/list', handler }),
    'file-mention: /file-mention/list route',
  )
}


export { name, inject, apply };
